Method.Implementation:
	try {
		Set tSC= $$$OK
		$$$TRACE("Begin OnMessage:"_pRequest.OriginalFilename)
		if ('$IsObject(pRequest.Stream)) {
 			Set tSC=$$$ERROR($$$EnsErrGeneral,"No Stream contained in StreamContainer Request")
		}
		if ($$$ISOK(tSC)) {

			Set tNameIn=##class(%File).GetFilename(pRequest.OriginalFilename)

			Set (tFilename,tFinalFilename)=..Adapter.CreateTimestamp(tNameIn,..Filename)

			If ""'=..TempFilename {
				Set tFilename=..Adapter.CreateTimestamp(tNameIn,..TempFilename)
			}

			Set currentDate = $ZDATETIME($HOROLOG,3,3)
			Set extractDate = $EXTRACT(currentDate,0,10)
			Set extractTime = $EXTRACT(currentDate,12,$LENGTH(currentDate))

			do ..valueToBeReplaced.SetAt(tFinalFilename,"%f")
			do ..valueToBeReplaced.SetAt(extractDate,"%CD")
			do ..valueToBeReplaced.SetAt(extractTime,"%CT")
			do ..valueToBeReplaced.SetAt(^ItfGlobal(..%ConfigName, "CurrentSequenceNumber"),"%#") //We are storing the current sequence number in ^ItfGlobal(<Service Name>, "CurrentSequenceNumber")

			//Replace %Q with the current time in the same format Ensemble's %Q Uses: no white space and periods between the values
			do ..valueToBeReplaced.SetAt($REPLACE($ZSTRIP(extractDate_"_"_extractTime,"*W"),":","."),"%Q")
			$$$TRACE("currentDate:>"_extractDate_">>currentTime:>>"_extractTime)

			Set updatedSuccessEmailSubject = ..replaceWithParticularFormat(..SuccessEmailSubject)
			Set updatedFailureEmailSubject = ..replaceWithParticularFormat(..FailureEmailSubject)
			Set updatedSuccessEmailbody = ..replaceWithParticularFormat(..SucessEmailBody)
			Set updatedFailureEmailbody = ..replaceWithParticularFormat(..FailureEmailBody)

			Set tFinalFilename = ..replaceWithParticularFormat(tFinalFilename)

			Set UpdatedActionOnTargetFile = ..replaceWithParticularFormat(..ActionOnTargetFile)

			Set tSC=..Adapter.PutStream(tFinalFilename, pRequest.Stream)
		}

		$$$TRACE("tFinalFilename:"_tFinalFilename_">>UpdatedActionOnTargetFile:"_UpdatedActionOnTargetFile)

		// For this Retry logic to work, Operation Setting "Reply Code Actions" should have a code with R , e.g E=RD or E=RF
		//$$$TRACE("Current Retry Count : "_..RetryCount)
		set MaxRetry = (..FailureTimeout/..RetryInterval)+1
		$$$TRACE("MaxRetry("_MaxRetry_") = FailureTimeout("_..FailureTimeout_") / RetryInterval("_..RetryInterval_") + 1")

		//Note: the following line is intended to skip this block if the ActionOnTargetFile field is empty, This is the intended behavior
		if ($$$ISOK(tSC) && (""'=..ActionOnTargetFile)){
			set tSC = ..Adapter.Rename(tFinalFilename,UpdatedActionOnTargetFile,..Adapter.FilePath)

			if ($$$ISOK(tSC)) {
			}
			else {
				Set tSC=$$$ERROR("ITFCOMMON:10101","Error renaming source file; ORIGINAL NAME: "_..Adapter.FilePath_"/"_tSource_"; ATTEMPTED NEW NAME: "_UpdatedActionOnSourceFile_". Make sure the specified directory name is visible and writable, and the target file does not already exist.")
			}
		}

		if ($$$ISOK(tSC)) { //If we don't have any errors yet
		//If we have an action on target file
			if (""'=..ActionOnTargetFile){
				if ($EXTRACT(UpdatedActionOnTargetFile)="/") {//If this is a full path 
					$$$TRACE("Set Permission with Rename:"_UpdatedActionOnTargetFile)
					Set tSC= ..SetPermissions(UpdatedActionOnTargetFile, ..FilePermissions)
				}
				else{
					$$$TRACE("Set Permission with Rename:"_..Adapter.FilePath_"/"_UpdatedActionOnTargetFile)
					Set tSC= ..SetPermissions(..Adapter.FilePath_"/"_UpdatedActionOnTargetFile, ..FilePermissions)
				}
			}
			else {
				$$$TRACE("Set Permission without Rename:"_tFinalFilename) 
				Set tSC = ..SetPermissions(..Adapter.FilePath_"/"_tFinalFilename, ..FilePermissions)
			}
		}

		//Sending Email
		If $$$ISOK(tSC)
		{
			If ..SuccessEmailSubject'= "" 
			{
				$$$TRACE("Sending alert for successful file transfer.")
				Set updatedSuccessEmailSubject = ..replaceWithParticularFormat(updatedSuccessEmailSubject)
				Set updatedSuccessEmailbody = ..replaceWithParticularFormat(updatedSuccessEmailbody)
				do ..ItfSendEmailOnSuccess(updatedSuccessEmailSubject, updatedSuccessEmailbody)
			}
			Else
			{
			$$$TRACE("No SuccessEmailSubject found; email will not be sent.")
			}
		}
		ElseIf (..RetryCount>=MaxRetry) //If we have run out of Retries
		{
			If ..FailureEmailSubject '= ""
			{
				$$$TRACE("Sending alert for failure in file transfer.")
				do ..valueToBeReplaced.SetAt(tSC,"%EM")
				Set updatedFailureEmailSubject = ..replaceWithParticularFormat(updatedFailureEmailSubject)
				Set updatedFailureEmailbody = ..replaceWithParticularFormat(updatedFailureEmailbody)
				do ..ItfSendEmailOnError(updatedFailureEmailSubject, updatedFailureEmailbody)
			}
			Else
			{
				$$$TRACE("No FailureEmailSubject found; email will not be sent.")
			}
			$$$TRACE("Error ocurred processing file: "_..Adapter.FilePath_"/"_UpdatedActionOnTargetFile_". Shutting down the component.")
			//Disable the operation
			Job ##class(Ens.Director).EnableConfigItem(..%ConfigName,0,1)
		}
		Else 
		{
			//If we have retries left
			$$$TRACE("Error Encountered; we have consumed "_..RetryCount_" out of "_MaxRetry_" retries.")
		}

		do ..IncrementSequenceNumber()
		$$$TRACE("Completed OnMessage:"_pRequest.OriginalFilename)
	}
	catch error {
		do ..IncrementSequenceNumber()
		$$$TRACE("Crash out of OnMessage:"_pRequest.OriginalFilename)
		throw error
	}
	Quit tSC

$$$TRACE("..ResetSequenceOnRestart="_..ResetSequenceOnRestart)
//If we are resetting the sequence number because the user wants us to or one is not configured
if ((..ResetSequenceOnRestart) || ($DATA(^ItfGlobal(..%ConfigName, "CurrentSequenceNumber")) = "0")) {
	//If there is a configured starting sequence number, replace the current number with it, or use the default
	if (""'=..StartingSequenceNumber) {
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..StartingSequenceNumber
		$$$TRACE("Replacing sequence number with starting sequence number: "_^ItfGlobal(..%ConfigName, "CurrentSequenceNumber"))
	}
	//If there is no configured starting sequence number, use a default
	else {
		$$$TRACE("No sequence numbers defined; setting to a default of 1")
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber")=	"1"
	}
}
else {
	$$$TRACE("CurrentSequenceNumber is "_^ItfGlobal(..%ConfigName, "CurrentSequenceNumber")_" and ResetSequenceOnRestart is disabled. Sequence number will not be reset")
}
Do ..VerifySequenceNumber()


if ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") < ..MinimumSequenceNumber //If sequence number is too low
{
	if ..SequenceIncrement < 0  { //If sequence number is too low and is descending, reset to maximum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MaximumSequenceNumber
		$$$TRACE("Sequence number has descended to below minimum value. Wrapping back to maximum value: "_..MaximumSequenceNumber)
	}
	if ..SequenceIncrement > 0 { //If sequence number is ascending, move to minimum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MinimumSequenceNumber
		$$$TRACE("Sequence number is beneath its minimum value.  Setting to minimum value: "_..MinimumSequenceNumber)
	}
}

if ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") > ..MaximumSequenceNumber //If sequence number is too high
{
	if ..SequenceIncrement < 0  {//If sequence number is too high and descending, set to maximum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MaximumSequenceNumber
		$$$TRACE("Sequence number is above maximum value, but descending. Setting to maximum value: "_..MaximumSequenceNumber)
	}
	if ..SequenceIncrement > 0 {// If sequence number is too high and ascending, reset to minimum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MinimumSequenceNumber
		$$$TRACE("Sequence number has ascended to above maximum value.  Wrapping back to minimum value: "_..MinimumSequenceNumber)
	}
}
if ..MinimumSequenceNumber > ..MaximumSequenceNumber //If the minimum and maximum violate each other
{
	$$$TRACE("MinimumSequnceNumber is greater than the MaximumSequnceNumber; setting CurrentSequenceNumber to zero.")
 	Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = 0
}

if (..EnableFilePermissions){ //If we want to alter target file permissions
	if (permissions="") {
		Set permissions="ug+rwx"
	}
	$$$TRACE("IHC.ITF.ITFCOMMON.FTP.Service.PassthroughService1.SetPermissions("_fullPath_","_permissions_")")
	Set tSC=..Adapter.SetPermissions(fullPath,permissions)
	Quit tSC
}
else { //If we do NOT want to alter target file permissions
	$$$TRACE("EnableFilePermissions is disabled; file permissions will not be altered.")
	Quit $$$OK
}
